#!/usr/bin/env node
// Drift check between lib/database.types.ts (generated by Supabase's type generator) and the database the
// migrations build.   npm run test:types-drift
//
//   PGHOST=<socket dir> PGPORT=<port> PGUSER=postgres node scripts/contract-check/types-drift.mjs [--types FILE] [--json FILE]
//
// The generated file says what every table, column, enum and function looked like when somebody last ran the
// generator against a real project. A migration that adds a column, changes a type or adds an RPC without the types
// being regenerated makes the typed client lie. This check reads the file with the TypeScript parser (no Supabase
// CLI, no network) and compares it with the catalog of the replayed cluster (scripts/db-replay.sh, as the contract
// check does). It fails on any difference in:
//   * the set of tables, views, enums and composite types of schema public (and the enum values, in order);
//   * per table or view: every column, its type (mapped as the generator maps it), whether Row allows null, whether
//     Insert may omit it (nullable, default, identity, generated), and `never` for identity ALWAYS / generated columns;
//   * per table: every foreign key (name, columns, referenced table and columns, isOneToOne);
//   * per function: the set of functions, each argument (name, type, optional or required) and the returned shape
//     (void, scalar, Json, the row of a table, or TABLE(...) columns, and whether it returns a set).
// A foreign key to another schema (profiles.id -> auth.users) is not in the generator's output and not compared.
// What it does not compare: the order of properties, comments, PostgrestVersion, the helper types at the end of
// the file, other schemas (auth, storage), and grants (the contract check and permissions.snapshot own those).
// Overloaded functions are reported, not compared: the generator emits a union for them and nothing here uses one.
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const opt = (name) => { const i = argv.indexOf(name); return i >= 0 ? argv[i + 1] : undefined; };
const FRONTEND = path.resolve(process.env.FRONTEND || path.join(HERE, "..", ".."));
const TYPES = path.resolve(opt("--types") || process.env.TYPES_FILE || path.join(FRONTEND, "lib", "database.types.ts"));
const ts = (() => { try { return createRequire(path.join(FRONTEND, "package.json"))("typescript"); } catch { return createRequire(import.meta.url)("typescript"); } })();

function sql(query) {
  try {
    return execFileSync("psql", ["-X", "-At", "-v", "ON_ERROR_STOP=1", "-d", process.env.PGDATABASE || "postgres", "-c", query], { encoding: "utf8", maxBuffer: 256 * 1024 * 1024, stdio: ["ignore", "pipe", "pipe"] }).trim();
  } catch (error) {
    console.error(`cannot read the replayed database (PGHOST=${process.env.PGHOST} PGPORT=${process.env.PGPORT}): ${String(error.stderr || error.message).trim().split("\n")[0]}`);
    process.exit(2);
  }
}
const rows = (query) => JSON.parse(sql(`select coalesce(json_agg(t), '[]'::json) from (${query}) t`));

const findings = [];
const drift = (key, message) => { if (!findings.some((f) => f.key === key)) findings.push({ key, message }); };   // one line per key

// ---------------------------------------------------------------- the generated file
if (!fs.existsSync(TYPES)) { console.error(`${TYPES} does not exist`); process.exit(2); }
const sf = ts.createSourceFile(TYPES, fs.readFileSync(TYPES, "utf8"), ts.ScriptTarget.Latest, true);
const compact = (text) => text.replace(/\s+/g, " ").replace(/\s*([|[\]{}();:,])\s*/g, "$1").replace(/,(?=[}\]])/g, "").replace(/^\|/, "").trim();
const textOf = (node) => compact(node.getText(sf));
const nameOf = (member) => (ts.isIdentifier(member.name) || ts.isStringLiteral(member.name) ? member.name.text : member.name.getText(sf));
const literalText = (node) => (node && ts.isLiteralTypeNode(node) ? (ts.isStringLiteral(node.literal) ? node.literal.text : node.literal.kind === ts.SyntaxKind.TrueKeyword ? true : node.literal.kind === ts.SyntaxKind.FalseKeyword ? false : node.literal.getText(sf)) : undefined);
const members = (node) => (node && ts.isTypeLiteralNode(node) ? node.members.filter(ts.isPropertySignature) : []);
const member = (node, name) => members(node).find((m) => nameOf(m) === name);

let database;
for (const statement of sf.statements) if (ts.isTypeAliasDeclaration(statement) && statement.name.text === "Database") database = statement.type;
const publicSchema = member(database, "public")?.type;
if (!publicSchema) { console.error(`${TYPES}: no Database["public"] type found; is this the output of the Supabase type generator?`); process.exit(2); }
const section = (name) => member(publicSchema, name)?.type;

/** Columns of a Row/Insert/Update/Args literal: name -> { optional, type (compact text) } */
function props(node) {
  const out = new Map();
  for (const m of members(node)) out.set(nameOf(m), { optional: Boolean(m.questionToken), type: m.type ? textOf(m.type) : "" });
  return out;
}

const tsTables = new Map(), tsViews = new Map(), tsFunctions = new Map(), tsEnums = new Map(), tsComposites = new Set();
for (const m of members(section("Tables"))) {
  const body = m.type;
  const relationships = [];
  const rel = member(body, "Relationships")?.type;
  if (rel && ts.isArrayTypeNode(rel) === false && ts.isTupleTypeNode(rel)) {
    for (const element of rel.elements) {
      const strings = (name) => { const t = member(element, name)?.type; return t && ts.isTupleTypeNode(t) ? t.elements.map(literalText) : literalText(t); };
      relationships.push({ name: strings("foreignKeyName"), columns: strings("columns"), ref: strings("referencedRelation"), refColumns: strings("referencedColumns"), oneToOne: strings("isOneToOne") });
    }
  }
  tsTables.set(nameOf(m), { row: props(member(body, "Row")?.type), insert: props(member(body, "Insert")?.type), update: props(member(body, "Update")?.type), relationships });
}
for (const m of members(section("Views"))) tsViews.set(nameOf(m), { row: props(member(m.type, "Row")?.type) });
for (const m of members(section("Functions"))) {
  const args = member(m.type, "Args")?.type;
  const returns = member(m.type, "Returns")?.type;
  let shape;
  if (returns && ts.isTypeLiteralNode(returns)) shape = { kind: "object", columns: props(returns) };
  else if (returns && ts.isArrayTypeNode(returns) && ts.isTypeLiteralNode(returns.elementType)) shape = { kind: "objects", columns: props(returns.elementType) };
  else shape = { kind: "scalar", type: returns ? textOf(returns) : "" };
  const setof = member(m.type, "SetofOptions")?.type;
  tsFunctions.set(nameOf(m), { args: args && ts.isTypeLiteralNode(args) ? props(args) : new Map(), shape, setTo: setof ? literalText(member(setof, "to")?.type) : undefined });
}
for (const m of members(section("Enums"))) {
  const values = [];
  const collect = (node) => { if (ts.isUnionTypeNode(node)) node.types.forEach(collect); else if (ts.isParenthesizedTypeNode(node)) collect(node.type); else values.push(literalText(node)); };
  collect(m.type);
  tsEnums.set(nameOf(m), values);
}
for (const m of members(section("CompositeTypes"))) tsComposites.add(nameOf(m));
// the runtime copy of the enums at the end of the file
let constantEnums;
for (const statement of sf.statements) {
  if (!ts.isVariableStatement(statement)) continue;
  for (const d of statement.declarationList.declarations) {
    if (!ts.isIdentifier(d.name) || d.name.text !== "Constants" || !d.initializer) continue;
    let init = d.initializer;
    if (ts.isAsExpression(init)) init = init.expression;
    const prop = (obj, name) => (ts.isObjectLiteralExpression(obj) ? obj.properties.find((p) => ts.isPropertyAssignment(p) && p.name.getText(sf) === name)?.initializer : undefined);
    const enumsNode = prop(prop(init, "public") || init, "Enums");
    if (enumsNode && ts.isObjectLiteralExpression(enumsNode)) {
      constantEnums = new Map();
      for (const p of enumsNode.properties) if (ts.isPropertyAssignment(p) && ts.isArrayLiteralExpression(p.initializer)) constantEnums.set(p.name.getText(sf), p.initializer.elements.map((e) => (ts.isStringLiteral(e) ? e.text : e.getText(sf))));
    }
  }
}

// ---------------------------------------------------------------- the replayed database
const pgTypes = new Map(rows(`select t.oid::int as oid, t.typname as name, t.typtype::text as kind, t.typcategory::text as cat, t.typelem::int as elem, t.typbasetype::int as base, n.nspname as ns from pg_type t join pg_namespace n on n.oid = t.typnamespace`).map((t) => [t.oid, t]));
const BASE = { int2: "number", int4: "number", int8: "number", float4: "number", float8: "number", numeric: "number", oid: "number", bool: "boolean", text: "string", varchar: "string", bpchar: "string", citext: "string", uuid: "string", date: "string", time: "string", timetz: "string", timestamp: "string", timestamptz: "string", interval: "string", bytea: "string", name: "string", inet: "string", json: "Json", jsonb: "Json" };
/** The TypeScript type the generator writes for a Postgres type (compact text). `?pg:name` when this check does not know the type. */
function tsType(oid) {
  const t = pgTypes.get(oid);
  if (!t) return `?pg:oid${oid}`;
  if (t.kind === "e") return t.ns === "public" ? `Database["public"]["Enums"]["${t.name}"]` : `?pg:enum ${t.ns}.${t.name}`;
  if (t.kind === "d") return tsType(t.base);
  if (t.cat === "A" && t.elem) return `${tsType(t.elem)}[]`;
  return BASE[t.name] || `?pg:${t.name}`;
}
const squash = (s) => compact(s);

const relations = rows(`select c.oid::int as oid, c.relname as name, c.relkind::text as kind from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind in ('r', 'p', 'f', 'v', 'm') order by 2`);
const columns = rows(`
  select c.relname as rel, a.attname as col, a.atttypid::int as typ, a.attnotnull as notnull, a.atthasdef as hasdef, a.attidentity::text as ident, a.attgenerated::text as gen
  from pg_attribute a join pg_class c on c.oid = a.attrelid join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r', 'p', 'f', 'v', 'm') and a.attnum > 0 and not a.attisdropped order by c.relname, a.attnum`);
const dbEnums = new Map(rows(`select t.typname as name, array_agg(e.enumlabel order by e.enumsortorder) as vals from pg_type t join pg_enum e on e.enumtypid = t.oid join pg_namespace n on n.oid = t.typnamespace where n.nspname = 'public' group by t.typname`).map((r) => [r.name, r.vals]));
const dbComposites = new Set(rows(`select c.relname as name from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'c'`).map((r) => r.name));
const fks = rows(`
  select k.conname as name, c.relname as rel, r.relname as ref, rn.nspname as ref_schema,
    (select array_agg(a.attname order by u.o) from unnest(k.conkey) with ordinality u(n, o) join pg_attribute a on a.attrelid = k.conrelid and a.attnum = u.n) as cols,
    (select array_agg(a.attname order by u.o) from unnest(k.confkey) with ordinality u(n, o) join pg_attribute a on a.attrelid = k.confrelid and a.attnum = u.n) as refcols,
    exists (select 1 from pg_index i where i.indrelid = k.conrelid and i.indisunique and i.indpred is null and i.indexprs is null
              and i.indkey::int2[] <@ k.conkey and k.conkey <@ i.indkey::int2[]) as one2one
  from pg_constraint k join pg_class c on c.oid = k.conrelid join pg_class r on r.oid = k.confrelid join pg_namespace n on n.oid = c.relnamespace join pg_namespace rn on rn.oid = r.relnamespace
  where k.contype = 'f' and n.nspname = 'public' and rn.nspname = 'public' order by 2, 1`);
const fns = rows(`
  select p.oid::int as oid, p.proname as name, p.proretset as retset, p.prorettype::int as ret, p.pronargdefaults as ndefaults, p.prokind::text as kind,
         coalesce(p.proargnames, array[]::text[]) as names, coalesce(p.proargmodes, array[]::"char"[])::text[] as modes,
         coalesce(p.proallargtypes, string_to_array(p.proargtypes::text, ' ')::oid[])::int[] as types, p.pronargs as nargs
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind in ('f', 'p') order by 2`);

const relationKind = new Map(relations.map((r) => [r.name, r.kind]));
const colsByRel = new Map();
for (const c of columns) (colsByRel.get(c.rel) || colsByRel.set(c.rel, []).get(c.rel)).push(c);

// ---------------------------------------------------------------- compare: relations, enums, composites
const dbTables = relations.filter((r) => r.kind === "r" || r.kind === "p" || r.kind === "f").map((r) => r.name);
const dbViews = relations.filter((r) => r.kind === "v" || r.kind === "m").map((r) => r.name);
const diffSets = (kind, inTypes, inDb, label = kind) => {
  for (const name of inDb) if (!inTypes.includes(name)) drift(`${kind}-missing:${name}`, `${label} ${name} exists in the database but not in the generated types: regenerate them`);
  for (const name of inTypes) if (!inDb.includes(name)) drift(`${kind}-extra:${name}`, `${label} ${name} is in the generated types but not in the database: regenerate them`);
};
diffSets("table", [...tsTables.keys()], dbTables);
diffSets("view", [...tsViews.keys()], dbViews);
diffSets("enum", [...tsEnums.keys()], [...dbEnums.keys()]);
diffSets("composite", [...tsComposites], [...dbComposites], "composite type");
for (const [name, values] of dbEnums) {
  const generated = tsEnums.get(name);
  if (generated && generated.join("|") !== values.join("|")) drift(`enum-values:${name}`, `enum ${name}: types say (${generated.join(", ")}), database says (${values.join(", ")})`);
  const constant = constantEnums?.get(name);
  if (constantEnums && generated && (constant || []).join("|") !== generated.join("|")) drift(`enum-constants:${name}`, `Constants.public.Enums.${name} is (${(constant || []).join(", ")}) but the Enums type says (${generated.join(", ")}): the file was edited by hand`);
}
if (constantEnums) for (const name of constantEnums.keys()) if (!tsEnums.has(name)) drift(`enum-constants:${name}`, `Constants.public.Enums.${name} has no matching Enums type`);

// ---------------------------------------------------------------- compare: columns
function expectedColumn(c) {
  const type = tsType(c.typ);
  const never = c.ident === "a" || c.gen !== "";
  const nullable = !c.notnull;
  const writable = never ? "never" : `${type}${nullable ? "|null" : ""}`;
  return { row: `${type}${nullable ? "|null" : ""}`, write: writable, insertOptional: nullable || c.hasdef || c.ident !== "" || c.gen !== "" };
}
function compareColumns(rel, generated, withWrites) {
  const expected = colsByRel.get(rel) || [];
  const byName = new Map(expected.map((c) => [c.col, c]));
  for (const c of expected) if (!generated.row.has(c.col)) drift(`column-missing:${rel}.${c.col}`, `${rel}.${c.col} exists in the database but not in the generated types (Row): regenerate them`);
  for (const col of generated.row.keys()) if (!byName.has(col)) drift(`column-extra:${rel}.${col}`, `${rel}.${col} is in the generated types but not in the database: regenerate them`);
  for (const c of expected) {
    const want = expectedColumn(c);
    const row = generated.row.get(c.col);
    if (!row) continue;
    if (row.optional) drift(`column-row-optional:${rel}.${c.col}`, `${rel}.${c.col}: Row marks it optional (Row properties are always present)`);
    if (squash(row.type) !== squash(want.row)) drift(`column-type:${rel}.${c.col}`, `${rel}.${c.col}: types say Row ${row.type}, database says ${want.row.replace("|null", " | null")}${c.notnull ? " (NOT NULL)" : " (nullable)"}`);
    if (!withWrites) continue;
    for (const [part, map] of [["Insert", generated.insert], ["Update", generated.update]]) {
      const w = map.get(c.col);
      if (!w) { drift(`column-missing:${rel}.${c.col}`, `${rel}.${c.col} is missing from ${part}`); continue; }
      const wantOptional = part === "Update" ? true : want.insertOptional;
      if (w.optional !== wantOptional) drift(`column-${part.toLowerCase()}-optional:${rel}.${c.col}`, `${rel}.${c.col}: ${part} ${w.optional ? "may omit" : "requires"} it, database says it is ${wantOptional ? "optional (nullable, has a default, identity or generated)" : "required (NOT NULL, no default)"}`);
      if (squash(w.type) !== squash(want.write)) drift(`column-${part.toLowerCase()}-type:${rel}.${c.col}`, `${rel}.${c.col}: types say ${part} ${w.type}, database says ${want.write.replace("|null", " | null")}`);
    }
  }
  if (withWrites) for (const [part, map] of [["Insert", generated.insert], ["Update", generated.update]]) for (const col of map.keys()) if (!byName.has(col)) drift(`column-extra:${rel}.${col}`, `${rel}.${col} is in ${part} of the generated types but not in the database`);
}
for (const [name, generated] of tsTables) if (relationKind.has(name)) compareColumns(name, generated, true);
for (const [name, generated] of tsViews) if (relationKind.has(name)) compareColumns(name, generated, false);

// ---------------------------------------------------------------- compare: foreign keys
for (const [name, generated] of tsTables) {
  if (!relationKind.has(name)) continue;
  const expected = fks.filter((f) => f.rel === name);
  for (const f of expected) {
    const g = generated.relationships.find((r) => r.name === f.name);
    if (!g) { drift(`fk-missing:${name}.${f.name}`, `foreign key ${f.name} (${name}.${f.cols.join(",")} -> ${f.ref}.${f.refcols.join(",")}) exists in the database but not in the generated types: embedded selects would not type-check`); continue; }
    const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
    if (!same(g.columns, f.cols) || g.ref !== f.ref || !same(g.refColumns, f.refcols)) drift(`fk-shape:${name}.${f.name}`, `foreign key ${f.name}: types say ${name}(${[g.columns].flat().join(",")}) -> ${g.ref}(${[g.refColumns].flat().join(",")}), database says ${name}(${f.cols.join(",")}) -> ${f.ref}(${f.refcols.join(",")})`);
    else if (g.oneToOne !== f.one2one) drift(`fk-one-to-one:${name}.${f.name}`, `foreign key ${f.name}: types say isOneToOne ${g.oneToOne}, database says ${f.one2one}`);
  }
  for (const g of generated.relationships) if (!expected.some((f) => f.name === g.name)) drift(`fk-extra:${name}.${g.name}`, `foreign key ${g.name} is in the generated types but not in the database`);
}

// ---------------------------------------------------------------- compare: functions
const dbFnNames = fns.map((f) => f.name);
for (const name of new Set(dbFnNames)) if (dbFnNames.filter((n) => n === name).length > 1) drift(`function-overload:${name}`, `function ${name} is overloaded; the generator emits a union and this check does not compare it. Compare it by hand or remove the overload`);
diffSets("function", [...tsFunctions.keys()], [...new Set(dbFnNames)]);
for (const f of fns) {
  const generated = tsFunctions.get(f.name);
  if (!generated || dbFnNames.filter((n) => n === f.name).length > 1) continue;
  // arguments: input modes only; the last pronargdefaults of them have defaults
  const inputs = [];
  const outs = [];
  f.types.forEach((typ, i) => {
    const mode = f.modes[i] || "i";
    const entry = { name: f.names[i] || "", typ };
    if (mode === "i" || mode === "b" || mode === "v") inputs.push(entry); else outs.push(entry);
  });
  const optional = new Set(inputs.slice(inputs.length - f.ndefaults).map((a) => a.name));
  for (const a of inputs) {
    if (!a.name) { drift(`function-arg-unnamed:${f.name}`, `function ${f.name} has an unnamed argument; PostgREST cannot call it by name and this check does not compare it`); continue; }
    const g = generated.args.get(a.name);
    if (!g) { drift(`function-arg-missing:${f.name}.${a.name}`, `${f.name}(${a.name}) exists in the database but not in the generated types: regenerate them`); continue; }
    if (g.optional !== optional.has(a.name)) drift(`function-arg-optional:${f.name}.${a.name}`, `${f.name}(${a.name}): types say ${g.optional ? "optional" : "required"}, database says ${optional.has(a.name) ? "optional (has a default)" : "required"}`);
    if (squash(g.type) !== squash(tsType(a.typ))) drift(`function-arg-type:${f.name}.${a.name}`, `${f.name}(${a.name}): types say ${g.type}, database says ${tsType(a.typ)}`);
  }
  for (const name of generated.args.keys()) if (!inputs.some((a) => a.name === name)) drift(`function-arg-extra:${f.name}.${name}`, `${f.name}(${name}) is in the generated types but not in the database`);
  // result
  const retType = pgTypes.get(f.ret);
  let want;
  if (retType?.name === "void") want = { kind: "scalar", type: "undefined" };
  else if (outs.length) want = { kind: f.retset ? "objects" : "object", columns: new Map(outs.map((o) => [o.name, tsType(o.typ)])) };
  else if (retType?.kind === "c") {
    const relName = rows(`select c.relname as name, c.relkind::text as kind from pg_class c join pg_type t on t.typrelid = c.oid where t.oid = ${f.ret}`)[0];
    const cols = relName ? colsByRel.get(relName.name) || [] : [];
    want = { kind: f.retset ? "objects" : "object", columns: new Map(cols.map((c) => [c.col, expectedColumn(c).row])), table: relName?.name };
  } else want = { kind: "scalar", type: f.retset ? `${tsType(f.ret)}[]` : tsType(f.ret) };
  const g = generated.shape;
  const describe = (s) => (s.kind === "scalar" ? s.type : `${s.kind === "objects" ? "set of " : ""}{${[...s.columns].map(([n, t]) => `${n}: ${typeof t === "string" ? t : t.type}`).join(", ")}}`);
  if (g.kind !== want.kind) { drift(`function-returns:${f.name}`, `${f.name} returns: types say ${describe(g)}, database says ${describe(want)}`); continue; }
  if (want.kind === "scalar") { if (squash(g.type) !== squash(want.type)) drift(`function-returns:${f.name}`, `${f.name} returns: types say ${g.type}, database says ${want.type}`); continue; }
  for (const [col, type] of want.columns) {
    const have = g.columns.get(col);
    if (!have) drift(`function-returns-column:${f.name}.${col}`, `${f.name} returns column ${col} in the database but not in the generated types`);
    else if (squash(have.type) !== squash(type)) drift(`function-returns-column:${f.name}.${col}`, `${f.name} returns ${col}: types say ${have.type}, database says ${type.replace("|null", " | null")}`);
  }
  for (const col of g.columns.keys()) if (!want.columns.has(col)) drift(`function-returns-column:${f.name}.${col}`, `${f.name} returns column ${col} in the generated types but not in the database`);
  if (want.table && generated.setTo !== want.table) drift(`function-returns-table:${f.name}`, `${f.name} returns rows of ${want.table}, SetofOptions.to in the types says ${generated.setTo}`);
}

// ---------------------------------------------------------------- output
findings.sort((a, b) => a.key.localeCompare(b.key));
for (const f of findings) console.log(`[DRIFT] ${f.key}: ${f.message}`);
const counts = `${tsTables.size} tables, ${tsViews.size} views, ${tsEnums.size} enums, ${tsFunctions.size} functions, ${[...tsTables.values()].reduce((n, t) => n + t.row.size, 0)} columns, ${[...tsTables.values()].reduce((n, t) => n + t.relationships.length, 0)} foreign keys`;
console.log(`${findings.length ? "FAIL" : "ok"}: ${path.relative(process.cwd(), TYPES) || TYPES} (${counts}) ${findings.length ? `differs from the replayed database in ${findings.length} place(s); regenerate it (docs/ARCHITECTURE.md)` : "matches the replayed database"}`);
const jsonOut = opt("--json");
if (jsonOut) fs.writeFileSync(jsonOut, JSON.stringify({ findings }, null, 1));
process.exit(findings.length ? 1 : 0);
